  "nodes": {
    "Component": [
      {
        "component_id": "comp_temperature_led",
        "name": "Temperature LED",
        "description": "Indicator LED that illuminates or blinks during temperature-related fault conditions.",
        "category": "indicator"
      },
      {
        "component_id": "comp_internal_compressor_led",
        "name": "Internal compressor LED",
        "description": "Indicator LED associated with internal compressor fault conditions; it illuminates with the temperature LED.",
        "category": "indicator"
      },
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "Power supply assembly referenced in cooling and positioning troubleshooting instructions.",
        "category": "power"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "Fan that cools the power supply and is referenced in troubleshooting instructions.",
        "category": "cooling"
      },
      {
        "component_id": "comp_internal_compressor",
        "name": "Internal compressor",
        "description": "Internal compressor that can overheat and turn off; its operation is included in troubleshooting tests.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_cover",
        "name": "Cover",
        "description": "Cover with louvers that must remain unblocked to allow air circulation for cooling internal components.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_air_inlet_filter",
        "name": "Compressor air inlet filter",
        "description": "Air inlet filter on the internal compressor; the manual describes replacing it as a troubleshooting step.",
        "category": "filtration"
      },
      {
        "component_id": "comp_air_flow_system",
        "name": "Air-flow system",
        "description": "Air-flow system inside the power supply, where ice may form after storage below freezing.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Internal board associated with the compressor and checked during troubleshooting.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Internal power board checked during troubleshooting of the compressor fault.",
        "category": "electrical"
      },
      {
        "component_id": "comp_start_circuit",
        "name": "Start circuit",
        "description": "Circuit involved in plasma start and referenced in troubleshooting instructions.",
        "category": "electrical"
      },
      {
        "component_id": "comp_torch",
        "name": "Torch",
        "description": "Torch used to produce an arc; its trigger is involved in the described operating and troubleshooting conditions.",
        "category": "cutting"
      }
    ]
  },
